/* From Uiverse.io by aguerquin  - Tags: hover, radio, stars, rating */
.__UIV_SCOPE__ .rating > label {
  margin-right: 4px;
}

.__UIV_SCOPE__ .rating:not(:checked) > input {
  display: none;
}

.__UIV_SCOPE__ .rating:not(:checked) > label {
  float: right;
  cursor: pointer;
  font-size: 30px;
}

.__UIV_SCOPE__ .rating:not(:checked) > label > svg {
  fill: #666;
  transition: fill 0.3s ease;
}

.__UIV_SCOPE__ .rating > input:checked ~ label > svg {
  fill: #ffa723;
}

.__UIV_SCOPE__ .rating:not(:checked) > label:hover ~ label > svg,
.__UIV_SCOPE__ .rating:not(:checked) > label:hover > svg {
  fill: #ff9e0b;
}

.__UIV_SCOPE__ #star1:hover ~ label > svg,
.__UIV_SCOPE__ #star1:hover > svg {
  fill: #a23c3c !important;
}

.__UIV_SCOPE__ #star2:hover ~ label > svg,
.__UIV_SCOPE__ #star2:hover > svg {
  fill: #99542d !important;
}

.__UIV_SCOPE__ #star3:hover ~ label > svg,
.__UIV_SCOPE__ #star3:hover > svg {
  fill: #9f7e18 !important;
}

.__UIV_SCOPE__ #star4:hover ~ label > svg,
.__UIV_SCOPE__ #star4:hover > svg {
  fill: #22885e !important;
}

.__UIV_SCOPE__ #star5:hover ~ label > svg,
.__UIV_SCOPE__ #star5:hover > svg {
  fill: #7951ac !important;
}

.__UIV_SCOPE__ #star1:checked ~ label > svg {
  fill: #ef4444;
}

.__UIV_SCOPE__ #star2:checked ~ label > svg {
  fill: #e06c2b;
}

.__UIV_SCOPE__ #star3:checked ~ label > svg {
  fill: #eab308;
}

.__UIV_SCOPE__ #star4:checked ~ label > svg {
  fill: #19c37d;
}

.__UIV_SCOPE__ #star5:checked ~ label > svg {
  fill: #ab68ff;
}
